from tinydb import where, TinyDB
db = TinyDB()
db.insert_multiple([{'a': 1}, {'a': None}, {'a': 5}, {}])
for op in ['<', '>', '<=', '>=']:
    try:
        res = db.search(getattr(where('a'), {'<':'__lt__','>':'__gt__','<=':'__le__','>=':'__ge__'}[op])(3))
        print(op, 'OK', [d['a'] for d in res if 'a' in d])
    except TypeError as e:
        print(op, 'CRASH', e)
